// 카톡_버튼 › 버튼정리: 사장님이 텔레그램 요약의 버튼을 누름 (카톡 읽기 3단계, 10/31).
// 콜백 'k|번호|동작' (동작 pub=가견적 발행, ask=빈칸 묻기 시작, later=나중에, ok=확인함, o0~o9=필름 주문 담당자). 사장님(가맹점 p_001 챗ID)이 누른 것만.
// 가견적 발행은 이 흐름의 저장 공간(staticData)에 '할 일' 로 적어 두고, 노트북이 kakao-jobs 로 가져간다. 글 내용은 적지 않는다.
// 필름 주문(11/1)은 주문받기가 적어 둔 sd.orders[번호] 의 담당자에게 문자 → sms 를 넘겨 문자보내기(SMS Gateway)가 보낸다.
const cq = $('버튼누름').first().json.callback_query || {};
const owner = ($input.first().json.fields || $input.first().json).텔레그램_챗ID;
if (!owner || String((cq.from || {}).id) !== String(owner)) return [];
const [k, job, act] = String(cq.data || '').split('|');
if (k !== 'k' || !/^[a-z0-9]{6}$/.test(job || '')) return [];
const sd = $getWorkflowStaticData('global');
// ask = 현장 빈칸을 업체 카톡 방에 물어보기 [시작해] (4단계, 10/31)
// rs·rc·rn = 능동 비서 답장 초안 [보내]·[고쳐서 보내]·[안 보냄] (11/4). rs 는 노트북이 가져가 그 업체 방에 보낸다
let 표시 = { pub: '⏳ 가견적 발행 중 — 노트북이 처리하면 링크가 옵니다', ask: '⏳ 업체에 묻는 중 — 노트북이 카톡을 보내면 알려 드립니다', later: '⏸ 나중에', ok: '✔ 확인함',
  rs: '⏳ 보내는 중 — 노트북이 카톡을 보내면 알려 드립니다', rc: '✏️ 아래 글을 눌러 복사 → 카톡 그 방에 붙여넣고 고쳐서 보내 주세요', rn: '🚫 안 보냄' }[act];
let sms = null, crew = null;
// y3a·y3d1·n3 = 인원 모집 '네' 한 팀원 [모두 넣기]·[1번 날 넣기]·[안 넣기] (11/1) — 인원모집 흐름(crew-act)이 처리하고 결과 글을 돌려준다
if (/^[yn]\d+(d\d+|a)?$/.test(act || '')) { crew = { rid: job, act }; 표시 = ''; }
if (/^o\d$/.test(act || '')) {
  const o = (sd.orders || {})[job];
  const p = o && o.people[Number(act.slice(1))];
  if (!p) 표시 = '❌ 주문 정보가 없습니다 (7일 지남) — 앱에서 필요량을 다시 고르거나 직접 보내 주세요';
  else if (o.sent) 표시 = '✔ 이미 ' + o.sent + '에게 보냈습니다';
  else {
    // 한국 번호 010… → +8210… (SMS Gateway 는 국제 형식)
    const d = p.phone.replace(/[^0-9+]/g, '');
    sms = { job, label: p.label, siteId: o.siteId, text: o.text, items: o.items || '', phone: d.startsWith('+') ? d : '+82' + d.replace(/^0/, '') };
    표시 = '';
  }
}
if (표시 === undefined) return [];
if (act === 'pub' || act === 'ask' || act === 'rs') {
  sd.jobs = (sd.jobs || []).filter((j) => Date.now() - j.at < 7 * 864e5);
  if (!sd.jobs.some((j) => j.job === job && j.action === act)) sd.jobs.push({ job, action: act, at: Date.now(), taken: false });
}
const msg = cq.message || {};
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// 답장 초안은 노트북이 「 」 안에 넣어 보낸다 → [고쳐서 보내] 는 눌러서 복사되게 <code> 로
const draft = (t) => { const m = String(t || '').match(/「([\s\S]*)」/); return m ? m[1] : ''; };
return [{ json: {
  query_id: cq.id, answer: act === 'pub' || act === 'ask' || act === 'rs' ? '받았습니다 — 노트북이 곧 처리' : sms || crew ? '처리 중' : '받았습니다', crew,
  chat_id: String((msg.chat || {}).id || owner), message_id: String(msg.message_id || ''),
  text: esc(String(msg.text || '').slice(0, 3800)) + (표시 ? '\n\n' + esc(표시) : '') + (act === 'rc' ? '\n<code>' + esc(draft(msg.text)) + '</code>' : ''), sms,
} }];

// 카톡_버튼 › 모집결과: 인원모집 흐름(crew-act)의 답 { msg } 을 텔레그램 글 끝에 붙인다 (11/1)
const pre = $('버튼정리').first().json;
const r = $input.first().json || {};
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const msg = r.msg || (r.error ? '❌ 못 했습니다 — 앱에서 직접 넣어 주세요' : '');
return [{ json: Object.assign({}, pre, { answer: r.msg ? '했습니다' : '못 했습니다', text: pre.text + (msg ? '\n\n' + esc(msg) : '') }) }];

// 카톡_버튼 › 문자결과: SMS Gateway(사장님 폰) 응답을 보고 텔레그램 글 끝에 ✅/❌ (2026-11-01).
// 보냈으면 같은 주문을 두 번 안 보내게 sent 를 적고, 앱 우편함(site-fill)에 '필름 주문' 단계를 넘긴다.
const pre = $('버튼정리').first().json;
const r = $input.first().json || {};
const ok = !r.error && !!(r.id || r.state) && String(r.state || '').toLowerCase() !== 'failed';
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sd = $getWorkflowStaticData('global');
const o = (sd.orders || {})[pre.sms.job];
if (ok && o) o.sent = pre.sms.label;
const why = r.error ? (r.error.message || r.error.description || JSON.stringify(r.error)) : '';
const today = new Date(Date.now() + 9 * 3600e3).toISOString().slice(0, 10);
return [{ json: Object.assign({}, pre, {
  ok,
  answer: ok ? '보냈습니다' : '못 보냄',
  text: pre.text + '\n\n' + (ok ? '✅ ' + esc(pre.sms.label) + '에게 보냈습니다 (사장님 폰) — 앱 필름 단계는 \'주문\' 으로 바뀝니다'
    : '❌ 못 보냄 — 폰의 SMS Gateway 앱이 켜져 있는지 확인하고, 위 글을 직접 보내 주세요' + (why ? '\n(' + esc(String(why).slice(0, 200)) + ')' : '')),
  // value = 주문한 필름 (앱이 보낸 items, 없으면 문자에서 인사·[현장] 줄을 뺀 것) — 앱 필름 탭에 '11/1 에이엔디·주문담당 ps170 1롤 주문' (사장님 11/1)
  fills: [{ siteId: pre.sms.siteId, kind: 'filmOrdered', room: pre.sms.label, at: today,
    value: pre.sms.items || pre.sms.text.split('\n').slice(1).filter((l) => l.trim() && !/^\[.*\]$/.test(l.trim())).join(' · ') }],
}) }];

// 카톡_버튼 › 표시: 텔레그램에 답하고 글을 고칠 내용 — 문자를 보냈으면 문자결과, 인원 모집이면 모집결과, 아니면 버튼정리 그대로
const pick = $('문자결과').isExecuted ? '문자결과' : $('모집결과').isExecuted ? '모집결과' : '버튼정리';
return [{ json: $(pick).first().json }];

// 카톡_버튼 › 주문받기: 현장관리 앱이 필름 줄마다 필요량을 다 고르면 POST film-order (사장님 열쇠, 2026-11-01 사장님).
// { siteId, name, text(주문 문자), people: [{label, phone}] } 를 이 흐름의 저장 공간(staticData)에 7일 두고,
// 텔레그램에 담당자 버튼을 띄운다 (카톡_알림 으로). 버튼 'k|번호|o0' 을 누르면 버튼정리가 사장님 폰(SMS Gateway)으로 문자를 보낸다.
// 담당자 번호는 글에 보여 준다 (사장님 11/1: 누구에게 가는지 보고 고르게). 버튼 콜백에는 번호 대신 순번만.
const b = $input.first().json.body || {};
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const siteId = s(b.siteId, 40), name = s(b.name, 80), text = s(b.text, 600);
if (!siteId || !text) throw new Error('siteId·text 가 비어 있음');
// sendTo = 앱 필름 탭의 📨 바로 주문 (11/1 사장님, 추가 주문도) — 텔레그램 버튼 없이 바로 문자. 앱이 결과를 받아 기록한다
if (b.sendTo && typeof b.sendTo === 'object') {
  const d = s(b.sendTo.phone, 20).replace(/[^0-9+]/g, '');
  if (d.length < 9) throw new Error('번호가 없음');
  return [{ json: { direct: true, sms: { label: s(b.sendTo.label, 24), text, phone: d.startsWith('+') ? d : '+82' + d.replace(/^0/, '') } } }];
}
const people = (Array.isArray(b.people) ? b.people : []).map((p) => ({ label: s(p && p.label, 24), phone: s(p && p.phone, 20).replace(/[^0-9+]/g, '') }))
  .filter((p) => p.label && p.phone.length >= 9).slice(0, 10);   // 주문처 담당자 전부 (카톡_알림 버튼 10개까지, 11/1)
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.orders = Object.fromEntries(Object.entries(sd.orders || {}).filter(([, o]) => now - o.at < 7 * 864e5));
let id = '';
while (!id || sd.orders[id]) id = (Math.random().toString(36).slice(2) + '000000').slice(0, 6);
sd.orders[id] = { siteId, name, text, items: s(b.items, 300), people, at: now };   // items = 앱 필름 탭 기록용 'ps170 1롤 · …'
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = ['🎞 <b>필름 주문 · ' + esc(name || siteId) + '</b>', '── 보낼 문자 ──', esc(text), ''];
const dash = (p) => p.replace(/^(\d{3})(\d{3,4})(\d{4})$/, '$1-$2-$3');
if (people.length) lines.push('── 주문처 · 담당자 ──', ...people.map((p) => '💬 ' + esc(p.label) + ' ' + dash(p.phone)), '');
lines.push(people.length ? '누구에게 보낼까요? 누르면 사장님 폰에서 바로 문자가 갑니다.'
  : '❓ 현장관리 설정 › 필름 주문처에 담당자 번호가 없습니다.');
return [{ json: { text: lines.join('\n'), html: true, buttons: [people.map((p, i) => ({ text: '💬 ' + p.label, data: 'k|' + id + '|o' + i }))] } }];

// 카톡_버튼 › 바로결과: 앱 📨 바로 주문의 SMS Gateway 응답 → 앱에 { ok, error } (11/1). 앱이 필름 탭에 기록한다
const r = $input.first().json || {};
const ok = !r.error && !!(r.id || r.state) && String(r.state || '').toLowerCase() !== 'failed';
const why = r.error ? (r.error.message || r.error.description || JSON.stringify(r.error)) : (ok ? '' : '응답 없음');
return [{ json: { ok, error: String(why).slice(0, 200) } }];

// 카톡_버튼 › 할일꺼내기: 노트북이 POST kakao-jobs (사장님 열쇠) 로 부른다 → 안 가져간 할 일을 주고 가져감 표시.
const sd = $getWorkflowStaticData('global');
sd.jobs = (sd.jobs || []).filter((j) => Date.now() - j.at < 7 * 864e5);
const out = sd.jobs.filter((j) => !j.taken).map((j) => ({ job: j.job, action: j.action, at: j.at }));
sd.jobs.forEach((j) => { j.taken = true; });
return [{ json: { jobs: out } }];
